<?php require_once __DIR__.'/../includes/layout.php';$u=require_role('paciente');if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$tipo=trim($_POST['tipo']??'');$desc=trim($_POST['descripcion']??'');if($tipo&&mb_strlen($tipo)<=100&&mb_strlen($desc)<=1000){db()->prepare('INSERT INTO donaciones(paciente_id,tipo,descripcion) VALUES((SELECT id FROM pacientes WHERE usuario_id=?),?,?)')->execute([$u['id'],$tipo,$desc]);flash('success','Tu ofrecimiento de donación fue registrado.');go('paciente/donaciones.php');}flash('error','Revisa los datos de tu donación.');}$items=all('SELECT * FROM donaciones WHERE paciente_id=(SELECT id FROM pacientes WHERE usuario_id=?) ORDER BY id DESC',[$u['id']]);header_ui('Mis donaciones');?><div class="page-intro"><h2>Un pequeño gesto, una gran ayuda 💗</h2><p>Registra un ofrecimiento de equipo ortopédico, movilidad, sangre o medicamentos. La institución evaluará cada solicitud antes de aceptarla.</p></div><div class="dashboard-grid"><section class="panel"><h2>Registrar donación</h2><form method="post" class="form-stack"><input type="hidden" name="csrf" value="<?=csrf()?>"><label>Equipo médico<select name="tipo" required><option value="">Selecciona</option><option>Aparatos ortopédicos</option><option>Muletas</option><option>Andadera</option><option>Silla de ruedas</option><option>Otro equipo médico</option><option>Donación de sangre (interés)</option><option>Donación de medicamentos (sujeta a revisión)</option></select></label><label>Descripción<textarea name="descripcion" maxlength="1000" rows="4" placeholder="Estado, cantidad, detalles..." required></textarea></label><button class="btn btn-primary">Registrar ofrecimiento</button></form></section><section class="panel"><h2>Mis ofrecimientos</h2><?php if(!$items):empty_state('Sin donaciones registradas','Aquí verás los equipos que ofrezcas.');else:foreach($items as $d):?><div class="appointment-row"><span class="feature-emoji">💗</span><div class="appointment-info"><strong><?=e($d['tipo'])?></strong><small><?=e($d['descripcion'])?></small></div><span class="badge badge-mint"><?=e($d['estado'])?></span></div><?php endforeach;endif;?></section></div><?php footer_ui();?>
